export function pick(rows: number[], bytes: Uint8Array, wide: Float64Array, s: string, n: number, k: number, j: string): number {
  return rows[k] + bytes[k] + wide[k] + s[k].length + (n as any as number[])[k] + Number(j[k]);
}
